import{_ as o,o as r,c as t,ag as i}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"ADR-0003: memU 双面集成 —— memu-cli 先行，memu-py 就绪后接入，皆从子模块源码构建","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0003-memu-cli-integration.md","filePath":"adr/0003-memu-cli-integration.md"}'),a={name:"adr/0003-memu-cli-integration.md"};function m(c,e,n,l,d,s){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0003-memu-双面集成-——-memu-cli-先行-memu-py-就绪后接入-皆从子模块源码构建" tabindex="-1">ADR-0003: memU 双面集成 —— memu-cli 先行，memu-py 就绪后接入，皆从子模块源码构建 <a class="header-anchor" href="#adr-0003-memu-双面集成-——-memu-cli-先行-memu-py-就绪后接入-皆从子模块源码构建" aria-label="Permalink to &quot;ADR-0003: memU 双面集成 —— memu-cli 先行，memu-py 就绪后接入，皆从子模块源码构建&quot;">​</a></h1><ul><li><strong>状态</strong>：Accepted（2026-07-16；2026-07-18 修订：双面连接策略 + 上游回归解决 + uv 缓存坑）</li><li><strong>日期</strong>：2026-07-16，修订 2026-07-18</li><li><strong>关联</strong>：<a href="./0002-memu-design-not-dependency.html">ADR-0002</a>（本 ADR 激活其 fallback）、<a href="./0001-llm-mode-memory.html">ADR-0001</a>、<a href="https://github.com/XnneHangLab/XnneHangLab/issues/493" target="_blank" rel="noreferrer">#493</a>、上游 <a href="https://github.com/NevaMind-AI/MemU/blob/main/docs/adr/0008-two-integration-surfaces-hooks-and-api.md" target="_blank" rel="noreferrer">memU ADR-0008</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><h3 id="动机-contributor-的-dogfooding-回路" tabindex="-1">动机：contributor 的 dogfooding 回路 <a class="header-anchor" href="#动机-contributor-的-dogfooding-回路" aria-label="Permalink to &quot;动机：contributor 的 dogfooding 回路&quot;">​</a></h3><p>维护者是 memU 的 <strong>contributor</strong>。把 memU 接进自己的 workspace 常驻使用，目的不止「与 wikimem 对照评测」，更是<strong>吃自己的狗粮</strong>：在真实高频使用中同时发现 memU 与本系统两边的问题与改进点， 反哺上游。这条回路在集成首日即被验证：</p><ul><li>集成 smoke 发现 embed 契约回归 → 上报 <a href="https://github.com/NevaMind-AI/memU/issues/499" target="_blank" rel="noreferrer">memU#499</a> → 上游<strong>当日</strong>以 <a href="https://github.com/NevaMind-AI/MemU/pull/504" target="_blank" rel="noreferrer">#504</a> 修复；</li><li>集成过程还实测出 uv 路径源的静默缓存坑（见「后果」）与 Windows 非 UTF-8 代码页管道乱码 （上游 <a href="https://github.com/NevaMind-AI/MemU/pull/513" target="_blank" rel="noreferrer">#513</a> 同期修复）。</li></ul><p>约束不变：<strong>子模块（镜像 <a href="https://github.com/XnneHangLab-Mirror/memU" target="_blank" rel="noreferrer"><code>XnneHangLab-Mirror/memU</code></a>） 源码构建，永不 pip install</strong>——对下述两个集成面都成立。</p><h3 id="上游架构-两个分层的集成面-memu-adr-0008" tabindex="-1">上游架构：两个分层的集成面（memU ADR-0008） <a class="header-anchor" href="#上游架构-两个分层的集成面-memu-adr-0008" aria-label="Permalink to &quot;上游架构：两个分层的集成面（memU ADR-0008）&quot;">​</a></h3><p>上游不是「只剩 memu-cli」，而是<strong>两个集成面、一个 base plane</strong>（共享同一 per-project store， 可自由混用）：</p><ul><li><strong>Surface A —— zero-code hooks</strong>（<code>memu-cli</code> + host adapters）：面向「装上就有记忆」的 drop-in 用户。hook 契约两条 seam：<code>on_turn</code>（回合后异步记录轨迹 + memorize，永不阻塞）、 <code>on_prompt</code>（生成前同步 retrieve 注入，token 预算，fail-open）。</li><li><strong>Surface B —— programmatic API</strong>（<code>memu-py</code>）：面向把 memU 内嵌进自己 agent 的 builder， 在代码里直接调 retrieve / memorize（in-process service 或 CLI/JSON），自主掌控时机、批量与 scope。</li></ul><p><code>memu-py</code> 正在经历<strong>大重构</strong>（ADR-0008 的 trajectory-as-source 方案：轨迹为唯一原始源， memory / skill / project 三线从同一轨迹语义抽取；CLI 收敛为 <code>memu memorize</code> / <code>memu retrieve</code> 唯一命令对，<code>-workspace</code> 命令<strong>无弃用期移除</strong>）。<strong>重构后的 memu-py 尚未就绪</strong>；就绪后接入。</p><h3 id="硬约束" tabindex="-1">硬约束 <a class="header-anchor" href="#硬约束" aria-label="Permalink to &quot;硬约束&quot;">​</a></h3><p><code>requires-python &gt;=3.13</code> + maturin/Rust 编译核（<code>memu._core</code>）；本项目钉在 3.11：</p><ul><li>CLI 面必然<strong>进程外</strong>（短生命周期子进程，上游明确按此设计——<code>memu/env.py</code>： &quot;entrypoint processes are short-lived&quot;）。</li><li>memu-py 面的进程形态<strong>待其就绪时定</strong>：若重构后支持 3.11 → 进程内 import；若仍 3.13 → 常驻 worker 进程 import（即本 ADR 初版「逃生门」的正式化，热路径从秒级降到毫秒-亚秒级）。</li></ul><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p><strong>双面连接，不二选一；两面都从 <code>packages/memU</code> 子模块源码构建。</strong></p><h3 id="_1-memu-cli-连接-surface-a-语义-已落地" tabindex="-1">1. memu-cli 连接（Surface A 语义，已落地） <a class="header-anchor" href="#_1-memu-cli-连接-surface-a-语义-已落地" aria-label="Permalink to &quot;1. memu-cli 连接（Surface A 语义，已落地）&quot;">​</a></h3><ol><li><strong>子模块</strong>：<code>packages/memU</code> 固定 mirror main（当前 <code>f51673e</code>，含 #504 修复）；不进 uv workspace（根 <code>pyproject.toml</code> <code>[tool.uv.workspace] exclude</code> 排除）。</li><li><strong>传输 = CLI 短生命周期子进程</strong>：插件每次调用 <code>uv run --isolated --no-project --python 3.13 --with packages/memU memu &lt;retrieve|commit&gt;</code>； <code>--no-project</code> 与 3.11 workspace 完全隔离；子进程环境强制 <code>PYTHONIOENCODING=utf-8</code> （非 UTF-8 Windows 代码页的管道乱码防护，任何 pin 都成立）。</li><li><strong>抽取在插件侧</strong>（上游 record seam 语义，与 wikimem 同构）：<code>on_after_turn</code> 后台单次 LLM 调用（默认继承 <code>lab.toml</code> chat 配置），复用 wikimem 的 <code>parse_extraction</code> 契约。本项目的 <code>HookPlugin.on_before_turn / on_after_turn</code> 与上游 hook 契约 <code>on_prompt / on_turn</code> 一一对应 ——<strong>这个插件事实上就是本项目自己的 host adapter</strong>。</li><li><strong>影子 markdown 是事实源</strong>：条目以 <code>name：content</code> 行追加到 <code>&lt;memory_dir&gt;/recall/&lt;category&gt;.md</code>（人可读可改、可 diff 回滚），整文件 <code>memu commit</code>； memU 按行 diff 重建 segments，SQLite 只是索引投影，可随时由影子文件重建。</li><li><strong>store 隔离</strong>：<code>MEMU_DB</code> / <code>MEMU_CONFIG_ENV</code> 指向 <code>&lt;memory_dir&gt;</code>——record/inject 两条 seam 共用同一 store 与 embedding 空间（上游 ADR-0009 硬要求），绝不与全局 <code>~/.memu/</code> 串味。</li><li><strong>embedding 端点是硬前置</strong>（commit/retrieve 都要向量化）：留空即禁用（警告一次）。</li><li><strong>fresh-build guard</strong>（实测坑的对策，见「后果」）：插件用 marker 记录子模块 commit， re-pin 后自动 touch <code>pyproject.toml</code> 迫使 uv 重建，杜绝静默旧构建。</li><li><strong>fail-open 与实验性 opt-in</strong>：结构性缺失 → 本会话禁用；单次失败/超时 → 本轮跳过；默认 不启用。</li></ol><h3 id="_2-memu-py-连接-surface-b-待上游重构就绪" tabindex="-1">2. memu-py 连接（Surface B，待上游重构就绪） <a class="header-anchor" href="#_2-memu-py-连接-surface-b-待上游重构就绪" aria-label="Permalink to &quot;2. memu-py 连接（Surface B，待上游重构就绪）&quot;">​</a></h3><ul><li>时机：上游 trajectory-as-source 重构落地、memu-py 形态稳定后接入；接入时<strong>修订本 ADR 或另立 ADR</strong> 确定进程形态（3.11 进程内 vs 3.13 常驻 worker）、与 CLI 面的共存方式（同一 store 可 混用是上游保证）及配置面。</li><li>预期分工：CLI 面 = 与上游 drop-in 路径同构的基线（对照评测、随上游演进）；PY 面 = 热路径 性能（毫秒-亚秒级检索）与代码级控制（自定批量/scope）。<strong>两面并存，不互相取代。</strong></li><li>同样<strong>只从子模块源码构建</strong>。</li></ul><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to &quot;理由&quot;">​</a></h2><ul><li><strong>契约面选 CLI 而非 import 内部 API（现阶段）</strong>：CLI 是上游当前唯一受支持的稳定面；子进程 形态把耦合缩到「三个子命令 + 五个环境变量」。Surface B 的 Python API 等上游自己宣布就绪， 不追它的重构中间态——ADR-0002 记录过追 Beta 内部 API 的教训，本次 pivot 与 #499 都是新证据。</li><li><strong>双面并存是上游设计直接支持的</strong>（分层共享 store，可自由混用），不是我们的私造组合。</li><li><strong>宿主侧抽取与影子 markdown</strong> 与上游 record-seam 语义、与 wikimem 的「人可审查」价值观同向； 两个后端共享抽取契约，评测对照公平。</li></ul><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><p><strong>正面</strong></p><ul><li>集成面最小且受上游支持；无常驻进程、无端口/健康探测（对比被替换的 FastAPI sidecar 净删一包）。</li><li>记忆事实源是本地 markdown：可 diff、可手改、可回滚；索引可重建。</li><li><strong>contributor 回路已被证明</strong>：#499 当日修复（#504）；后续 memu-py 接入延续同一回路。</li></ul><p><strong>负面 / 代价</strong></p><ul><li><strong>每次召回付一次子进程成本</strong>：实测热路径（Windows，本地 embedding mock，带数据 retrieve 三次）<strong>2.1–2.4 s/次</strong>，慢于 wikimem 进程内毫秒级。可接受为实验代价；根治靠 Surface B （memu-py）接入。</li><li>首次调用触发 maturin 源码构建（需 <strong>Rust 工具链</strong> + uv 可解析的 Python 3.13），构建期间 召回 fail-open 不注入。</li><li><strong>uv 路径源静默缓存坑（实测）</strong>：uv 对路径依赖的 cache key 只看 <code>pyproject.toml</code> 等构建 文件的 <strong>mtime</strong>。子模块 re-pin 后若版本号没变、<code>pyproject.toml</code> 字节未变（checkout 不碰它 → mtime 不变），uv 会<strong>静默复用旧构建</strong>——<code>--refresh-package</code> 与 <code>uv cache clean &lt;pkg&gt;</code> 均无效，唯 touch 构建文件有效。对策：插件内置 fresh-build guard（marker + touch，自动）； 手动跑 CLI 时 re-pin 后需 <code>touch packages/memU/pyproject.toml</code>。可向上游建议在其 <code>pyproject.toml</code> 加 <code>[tool.uv] cache-keys = [{ file = &quot;pyproject.toml&quot; }, { git = { commit = true } }]</code> 一劳永逸。</li><li>承接 memU 的 Beta 抖动：<strong>已宣告的下一个破坏性变更</strong>是 CLI 命令收敛（<code>memu memorize</code> / <code>memu retrieve</code> 成为唯一命令对，现用的 <code>commit</code> / <code>list-files</code> / <code>-workspace</code> 世代整体退场， 无弃用期）——未来 re-pin 跨过该 cut 时插件需同步适配。缓解 = 子模块 pin + 最小契约面 + contributor 对上游 roadmap 的一手掌握。</li></ul><p><strong>已解决（历史记录）</strong></p><ul><li><s>上游 main embed 契约回归（client 返回元组、agentic 面按裸列表消费，<code>commit</code>/带数据 <code>retrieve</code> 不可用）</s>：上报 <a href="https://github.com/NevaMind-AI/memU/issues/499" target="_blank" rel="noreferrer">memU#499</a> （2026-07-16）→ 上游当日 <a href="https://github.com/NevaMind-AI/MemU/pull/504" target="_blank" rel="noreferrer">#504</a> 修复 → re-pin <code>f51673e</code> 后 keyless round-trip smoke（commit → retrieve 命中返回）<strong>通过</strong> （2026-07-18）。</li></ul><p><strong>复审条件</strong></p><ul><li><strong>memu-py 重构就绪</strong> → 启动 Surface B 接入（修订本 ADR：进程形态、配置、与 CLI 面分工）。</li><li>对照评测显示 memU 无明显收益，或维护成本超预期 → 退回仅 wikimem。</li><li>上游 CLI 命令 cut 落地 → re-pin + 插件适配（<code>commit</code> → 新 <code>memorize</code> 语义映射）。</li></ul><h2 id="实现落点" tabindex="-1">实现落点 <a class="header-anchor" href="#实现落点" aria-label="Permalink to &quot;实现落点&quot;">​</a></h2><ul><li>子模块：<code>packages/memU</code>（mirror main <code>f51673e</code>）</li><li>插件：<code>src/lab/plugins/memu/{__init__.py,plugin.toml}</code>（CLI 子进程 + 宿主侧抽取 + 影子文件 <ul><li>fresh-build guard + UTF-8 stdio）</li></ul></li><li>workspace 排除：<code>pyproject.toml</code> <code>[tool.uv.workspace] exclude</code></li><li>测试：<code>tests/test_memu_plugin.py</code>（假 CLI + env 隔离不变量 + fresh-build guard）</li><li>文档：<code>docs/guide/architecture/memu-memory.md</code>（含 keyless smoke 与 re-pin runbook）</li><li>待接入：memu-py（Surface B）—— 上游就绪后另行修订</li></ul>',33)])])}const p=o(a,[["render",m]]);export{g as __pageData,p as default};
